<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

use OpenApi\Attributes as OA;
use Throwable;

use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create\TemplateAssetCreateUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetUidVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetCodeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTypeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetContentVO;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\MagicLinkService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetEnabledVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create\TemplateAssetCreateParams;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create\TemplateAssetCreateResult;

class TemplateAssetCreateController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly SqlTemplate $sql,
    private readonly TemplateAssetCreateUsecase $createUsecase,
    private readonly Context $context,
    private readonly MagicLinkService $links,
  ) {
  }
  #[OA\Post(path: "/api/document/template-asset", tags: ["Template asset"], description:"Create",
        requestBody: new OA\RequestBody(content: new OA\JsonContent( type: "object", ref:"#/components/schemas/TemplateAssetApiDTO")),
        responses: [
            new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateAssetApiDTO")),
            new OA\Response(response: 422, description: "Constraint error"),
        ]  )]
  public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Create Template asset");
    $span = $this->startSpan("Create Template asset");
    $this->sql->begin();
    try {
      $value = $this->readTemplateAsset($request);
      $result = $this->createUsecase->create($value);
      $this->sql->commit();
      $value = $this->mapTemplateAsset($request, $result);
      $encoded = json_encode($value);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(201)
        ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $this->sql->close();
      $span->end();
    }
  }

  private function readTemplateAsset(ServerRequestInterface $request): TemplateAssetCreateParams
  {
    $this->logDebug("Read entity for Template asset");
    $span = $this->startSpan("Read entity for Template asset");
    try {
      $parsed = $request->getParsedBody() ?? [];
      $body = is_array($parsed) ? $parsed : get_object_vars( $parsed );      $errorsList = new ConstraintFailList();
      $value = new TemplateAssetCreateParams();
        $valueUid = TemplateAssetUidVO::tryFrom($body['uid']??null, $errorsList);
        if( null !== $valueUid) {
          $value->uid($valueUid);
        }
      if( in_array('tenant', array_keys($body)) ) {
        $valueTenant = TemplateAssetTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList);
        if( null !== $valueTenant) {
          $value->tenant($valueTenant);
        }
      }
        $valueCode = TemplateAssetCodeVO::tryFrom($body['code']??null, $errorsList);
        if( null !== $valueCode) {
          $value->code($valueCode);
        }
        $valueType = TemplateAssetTypeVO::tryFrom($body['type']??null, $errorsList);
        if( null !== $valueType) {
          $value->type($valueType);
        }
      $content = $body['content']??null;
      $preffixContent = $this->context->getBaseUrl() . '/api/document/template-asset/-/temp-content?temp=';
      if ( null !== $content && strpos($content, $preffixContent)===0) {
        $valueContent = TemplateAssetContentVO::tryFromTemporal(base64_decode( substr($content, strlen($preffixContent)) ), $errorsList);
        if( null !== $valueContent) {
          $value->content($valueContent);
        }
      }
        $value->version(TemplateAssetVersionVO::tryFrom($body['version']??null, $errorsList));
      if( $errorsList->hasErrors() ) {
        throw $errorsList->asConstraintException();
      }
      return $value;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function mapTemplateAsset(ServerRequestInterface $request, TemplateAssetCreateResult $value): TemplateAssetApiDTO
  {
    $this->logDebug("Map entity to output dto for Template asset");
    $span = $this->startSpan("Map entity to output dto for Template asset");
    try {
      $tenant = $value->getTenant();
      $dto = new TemplateAssetApiDTO();
      $dto->uid = $value->getUid();
      $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
      $dto->code = $value->getCode();
      $dto->type = $value->getType();
      if (null !== $value->getContent()) {
        $url = $this->context->getBaseUrl() . '/api/document/template-asset/' . ($value->getUid() ?? '-'). '/content';
        $dto->content = $this->links->create($url, $request);
      }
      $dto->enabled = $value->isEnabled();
      $dto->version = $value->getVersion();
      return $dto;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
